-- Services
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('installation-cctv', 'Installation de caméras CCTV', 'Installation professionnelle de systèmes de vidéosurveillance analogiques et HD pour habitations, commerces et entreprises.', 'Nous concevons et installons des systèmes de vidéosurveillance CCTV complets et sur mesure : étude des angles morts, choix des caméras, câblage soigné, enregistrement sécurisé et formation à l’utilisation. Une installation propre, discrète et durable, réalisée par nos techniciens certifiés.', 'video', 'assets/images/tech-mount.jpg', '["Étude de site et plan d’implantation","Fourniture de caméras HD / Full HD certifiées","Câblage, pose et réglage des angles de vue","Enregistreur DVR avec disque dur de surveillance","Formation de vos équipes à l’exploitation","Garantie installation 12 mois"]'::jsonb, 'Commerces, résidences, entrepôts, bureaux', '1 à 3 jours selon le site', true, 10)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('cameras-ip-wifi', 'Caméras IP & Wi-Fi', 'Caméras réseau haute définition (IP PoE) et caméras Wi-Fi intelligentes, avec vision nocturne et détection de mouvement.', 'Profitez d’images ultra-nettes jusqu’en 4K grâce aux caméras IP PoE, ou optez pour la simplicité des caméras Wi-Fi sans gros travaux. Détection intelligente de personnes, vision nocturne couleur, audio bidirectionnel : nous installons la solution adaptée à votre budget et à vos locaux.', 'wifi', 'assets/images/camera-building.jpg', '["Caméras IP 2MP à 8MP (4K) PoE","Caméras Wi-Fi intérieures et extérieures","Vision nocturne infrarouge ou couleur","Détection intelligente de mouvement / IA","Raccordement réseau et switch PoE","Configuration complète incluse"]'::jsonb, 'Habitations, PME, sites sensibles', '1 à 2 jours', true, 20)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('surveillance-distance', 'Surveillance à distance', 'Visualisez vos caméras en direct depuis votre smartphone, tablette ou ordinateur, où que vous soyez, 24h/24.', 'Gardez un œil sur votre domicile ou votre entreprise depuis n’importe où dans le monde. Nous configurons l’accès distant sécurisé sur vos appareils : direct, relecture des enregistrements, alertes instantanées en cas d’intrusion et partage d’accès avec vos proches ou collaborateurs.', 'phone', 'assets/images/remote-tablet.jpg', '["Application mobile iOS & Android configurée","Alertes push en cas de détection","Relecture des enregistrements à distance","Accès multi-utilisateurs avec droits gérés","Connexion chiffrée et sécurisée","Assistance à la prise en main"]'::jsonb, 'Particuliers, gérants, multi-sites', '2 à 4 heures', true, 30)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('systemes-alarme', 'Systèmes d’alarme anti-intrusion', 'Centrales d’alarme filaires et sans fil avec détecteurs de mouvement, contacts d’ouverture et sirènes dissuasives.', 'Protégez vos locaux contre les intrusions avec un système d’alarme fiable : détecteurs de mouvement, contacts de porte et fenêtre, sirène extérieure et alertes sur votre téléphone. Nos centrales sans fil s’installent sans travaux et restent opérationnelles même en cas de coupure de courant.', 'bell', 'assets/images/service-alarm.jpg', '["Centrale d’alarme avec batterie de secours","Détecteurs de mouvement et d’ouverture","Sirène intérieure / extérieure dissuasive","Alertes SMS et application mobile","Télécommandes et badges utilisateurs","Test complet et mise en service"]'::jsonb, 'Résidences, boutiques, dépôts', '1 journée', true, 40)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('controle-acces', 'Contrôle d’accès électronique', 'Badge, code ou empreinte digitale : maîtrisez qui entre dans vos locaux et gardez un historique complet des passages.', 'Sécurisez les zones sensibles de votre entreprise grâce au contrôle d’accès biométrique ou par badge. Gérez les autorisations par utilisateur, par horaire et par porte, et consultez l’historique des entrées et sorties. Idéal aussi pour la gestion de présence du personnel.', 'key', 'assets/images/service-access.jpg', '["Lecteurs biométriques (empreinte, visage)","Badges RFID et claviers à code","Ventouses et gâches électriques","Logiciel de gestion des accès","Historique et rapports de présence","Formation de l’administrateur"]'::jsonb, 'Bureaux, écoles, cliniques, entrepôts', '1 à 3 jours', true, 50)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('interphones-visiophones', 'Interphones & visiophones', 'Voyez et parlez à vos visiteurs avant d’ouvrir : platines de rue vidéo, moniteurs intérieurs et ouverture à distance.', 'Accueillez vos visiteurs en toute sécurité grâce aux visiophones dernière génération : image couleur jour et nuit, conversation bidirectionnelle, ouverture du portail depuis le moniteur ou le smartphone. Solutions pour villas, résidences collectives et immeubles de bureaux.', 'monitor', 'assets/images/service-intercom.jpg', '["Platine de rue anti-vandale avec caméra","Moniteur intérieur tactile 7” couleur","Ouverture de porte / portail à distance","Vision nocturne automatique","Version connectée smartphone disponible","Interphonie multi-postes pour immeubles"]'::jsonb, 'Villas, résidences, immeubles', '1 journée', true, 60)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('maintenance-depannage', 'Maintenance & dépannage', 'Contrats de maintenance préventive et dépannage rapide de vos installations existantes, toutes marques.', 'Une caméra en panne, une image dégradée, un enregistreur qui ne répond plus ? Nos techniciens interviennent rapidement pour diagnostiquer et réparer vos équipements, quelle que soit la marque. Nos contrats de maintenance incluent des visites préventives pour garantir un système toujours opérationnel.', 'tool', 'assets/images/tech-wiring.jpg', '["Signalement de panne en ligne avec ville et urgence","Diagnostic sur site sous 48 h","Réparation et remplacement de matériel","Nettoyage et réglage des caméras","Vérification des enregistrements et disques","Contrats annuels avec visites programmées","Assistance technique 7j/7 pour les pros"]'::jsonb, 'Sites déjà équipés, professionnels', 'Intervention sous 24 à 48 h', true, 70)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.services (slug, title, short_description, long_description, icon_name, image_path, includes, ideal_for, duration_label, is_published, sort_order)
values ('configuration-securisation', 'Configuration & sécurisation', 'Paramétrage avancé de vos enregistreurs et réseaux, mots de passe, sauvegardes et protection contre les accès non autorisés.', 'Un système mal configuré est une faille de sécurité. Nous auditons et sécurisons votre installation : changement des mots de passe par défaut, mises à jour firmware, segmentation réseau, sauvegarde des configurations et optimisation de la qualité d’enregistrement pour une durée de stockage maximale.', 'sliders', 'assets/images/control-config.jpg', '["Audit de sécurité de l’existant","Mises à jour firmware des équipements","Politique de mots de passe renforcée","Optimisation compression / stockage","Sauvegarde et documentation du système","Rapport d’intervention détaillé"]'::jsonb, 'Entreprises, sites sensibles', 'Une demi-journée à 1 jour', true, 80)
on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon_name = excluded.icon_name, image_path = excluded.image_path, includes = excluded.includes, ideal_for = excluded.ideal_for, duration_label = excluded.duration_label, is_published = true, sort_order = excluded.sort_order, updated_at = now();

