-- FAQ
insert into public.faqs (question, answer_html, is_published, sort_order) values ('Combien coûte une installation de vidéosurveillance ?', 'Nos packs démarrent à 200 000 FCFA pour 4 caméras (tarif indicatif à revoir), puis le prix dépend du nombre de caméras, de la technologie (HD, IP, Wi-Fi), de la durée d’enregistrement souhaitée et de la configuration de vos locaux. C’est pourquoi nous commençons toujours par une <strong>étude de site</strong>, suivie d’un devis détaillé sous 24 h — sans aucun engagement de votre part.', true, 10)
on conflict (question) do update set answer_html = excluded.answer_html, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (question, answer_html, is_published, sort_order) values ('Puis-je voir mes caméras depuis mon téléphone ?', 'Oui. Tous nos systèmes incluent la visualisation à distance gratuite sur smartphone (iOS et Android), tablette et ordinateur : images en direct, relecture des enregistrements et alertes instantanées en cas de détection de mouvement. Nous configurons tout sur vos appareils le jour de l’installation.', true, 20)
on conflict (question) do update set answer_html = excluded.answer_html, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (question, answer_html, is_published, sort_order) values ('Pendant combien de temps les images sont-elles conservées ?', 'Cela dépend de la capacité du disque dur et du nombre de caméras. À titre d’exemple, un disque de 2 To conserve environ <strong>30 jours d’images pour 4 caméras</strong> en enregistrement sur détection. Nous dimensionnons le stockage selon vos obligations et vos habitudes, de 15 à 90 jours.', true, 30)
on conflict (question) do update set answer_html = excluded.answer_html, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (question, answer_html, is_published, sort_order) values ('Faut-il une connexion internet pour que les caméras fonctionnent ?', 'Non : l’enregistrement se fait localement sur le disque dur de l’enregistreur, même sans internet. La connexion n’est nécessaire que pour la consultation à distance depuis votre téléphone. En cas de coupure, le système continue d’enregistrer normalement.', true, 40)
on conflict (question) do update set answer_html = excluded.answer_html, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (question, answer_html, is_published, sort_order) values ('Intervenez-vous en dehors de San Pedro ?', 'Oui, depuis notre siège de San Pedro (Quartier Cité, Rue des Banques), nous réalisons des installations dans toute la Côte d’Ivoire : Abidjan, Bouaké, Yamoussoukro, Daloa, Korhogo, Man et Yamoussoukro… Les frais de déplacement sont simplement intégrés au devis, de façon transparente. Le suivi peut ensuite se faire à distance dans la plupart des cas.', true, 50)
on conflict (question) do update set answer_html = excluded.answer_html, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (question, answer_html, is_published, sort_order) values ('Comment signaler une panne sur mon installation ?', 'Utilisez notre <a href="panne.html"><strong>espace dédié aux pannes</strong></a> : indiquez votre nom, votre téléphone, la <strong>ville</strong> et le quartier du site, l’équipement concerné, ce qui ne fonctionne plus et le niveau d’urgence. Nous savons immédiatement <strong>qui vous êtes, quel est le problème et où intervenir</strong>.', true, 60)
on conflict (question) do update set answer_html = excluded.answer_html, is_published = true, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (question, answer_html, is_published, sort_order) values ('Quelle garantie et quel service après-vente proposez-vous ?', 'Le matériel est garanti jusqu’à <strong>2 ans</strong> (garantie constructeur) et notre installation est garantie <strong>12 mois</strong>. Notre service après-vente, basé à San Pedro, Côte d’Ivoire, intervient sous 24 à 48 h. Nous proposons également des contrats de maintenance annuelle avec visites préventives et astreinte 7j/7 pour les professionnels.', true, 70)
on conflict (question) do update set answer_html = excluded.answer_html, is_published = true, sort_order = excluded.sort_order, updated_at = now();
